const b = $input.first().json.body || $input.first().json;
const ask = Number(b.ask) || 235000;
const offer = Math.round(ask * 0.982);
const rent = Number(b.rent) || Math.round(1.18 * ((Number(b.sqft) || 1560) * 1.12) + (Number(b.beds) || 3) * 90);
const tax = Math.round((ask * 0.012) / 12);
const hoa = 220;
const insurance = Math.round((ask * 0.0046) / 12);
const principal = offer * 0.5;
const r = 0.07 / 12;
const n = 360;
const mortgage = Math.round((principal * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1));
const noi = rent - tax - hoa - insurance;
const afterDebt = noi - mortgage;
const score = Math.max(38, Math.min(96, Math.round(42 + Math.min(40, noi / 45))));
const rec = score >= 78 ? 'pursue' : score >= 62 ? 'watch' : 'pass';
return [{
  json: {
    runId: b.runId,
    callbackUrl: b.callbackUrl,
    result: {
      title: b.query,
      subtitle: 'n8n property underwriting · 7% / 30yr / 50% down',
      investorScore: score,
      recommendation: rec,
      summary: `Offer ${offer} vs ask ${ask}. NOI ${noi}/mo, after debt ${afterDebt}/mo.`,
      metrics: [
        { label: 'Ask', value: '$' + ask.toLocaleString() },
        { label: 'Offer', value: '$' + offer.toLocaleString() },
        { label: 'Rent (est.)', value: '$' + rent + '/mo' },
        { label: 'NOI / Cash Flow', value: '$' + noi + '/mo' },
        { label: 'After debt', value: '$' + afterDebt + '/mo' },
        { label: 'Mortgage', value: '$' + mortgage + '/mo', hint: '7% · 30yr · 50% down' }
      ],
      cashFlow: { rent, tax, hoa, insurance, mortgage, noi, afterDebt, ask, offer },
      sections: [
        { heading: 'n8n notes', body: 'Swap this Code node for Apify / Zillow / RentCast HTTP requests. RIP still stores the report.', bullets: ['Cash flow is NOI before debt, matching High ROI Picks.', 'Post back to callbackUrl with x-webhook-secret.'] }
      ]
    }
  }
}];
